def board_words(board, words):
    root = {}
    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
        node['$'] = word
    rows = len(board)
    cols = len(board[0]) if rows else 0
    grid = [list(row) for row in board]
    found = []

    def walk(r, c, parent):
        ch = grid[r][c]
        node = parent.get(ch)
        if node is None:
            return
        word = node.pop('$', None)
        if word is not None:
            found.append(word)
        grid[r][c] = '.'
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '.':
                walk(nr, nc, node)
        grid[r][c] = ch
        if not node:
            del parent[ch]

    for r in range(rows):
        for c in range(cols):
            walk(r, c, root)
    return sorted(found)

